<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'
import {createWarehouse,getWarehouses,type Warehouse} from '@/services/business'
import {useAuthStore} from '@/stores/auth'

const auth=useAuthStore(),items=ref<Warehouse[]>([]),loading=ref(false),saving=ref(false),error=ref(''),notice=ref('')
const form=reactive({code:'',name:'',address:'',status:'ACTIVE'})
async function load(){loading.value=true;error.value='';try{items.value=await getWarehouses()}catch{error.value='Không thể tải danh sách kho.'}finally{loading.value=false}}
async function create(){saving.value=true;error.value='';try{const value=await createWarehouse(form);notice.value=`Đã tạo kho ${value.name}.`;Object.assign(form,{code:'',name:'',address:'',status:'ACTIVE'});await load()}catch{error.value='Không thể tạo kho. Kiểm tra mã kho không bị trùng.'}finally{saving.value=false}}
onMounted(load)
</script>

<template><section class="p-6 lg:p-8"><div><p class="text-sm font-semibold text-cyan-700">Quản lý đa kho</p><h2 class="text-3xl font-bold">Kho hàng</h2></div><p v-if="error" class="mt-4 rounded-lg bg-red-50 p-3 text-red-800">{{error}}</p><p v-if="notice" class="mt-4 rounded-lg bg-emerald-50 p-3 text-emerald-800">{{notice}}</p><form v-if="auth.hasPermission('warehouse.manage')" class="mt-6 grid gap-3 rounded-xl border bg-white p-5 md:grid-cols-2" @submit.prevent="create"><label class="grid gap-1 text-sm">Mã kho<input v-model.trim="form.code" required maxlength="50" pattern="[A-Za-z0-9_-]+" class="rounded-lg border p-2"></label><label class="grid gap-1 text-sm">Tên kho<input v-model.trim="form.name" required maxlength="150" class="rounded-lg border p-2"></label><label class="grid gap-1 text-sm md:col-span-2">Địa chỉ<input v-model.trim="form.address" maxlength="500" class="rounded-lg border p-2"></label><label class="grid gap-1 text-sm">Trạng thái<select v-model="form.status" class="rounded-lg border p-2"><option value="ACTIVE">Đang hoạt động</option><option value="INACTIVE">Ngừng hoạt động</option></select></label><button :disabled="saving" class="self-end rounded-lg bg-cyan-700 px-4 py-2 text-white disabled:opacity-50">{{saving?'Đang lưu…':'Tạo kho'}}</button></form><p v-if="loading" class="mt-6 text-slate-500">Đang tải…</p><div v-else class="mt-6 overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4">Mã</th><th class="p-4">Tên kho</th><th class="p-4">Địa chỉ</th><th class="p-4">Trạng thái</th></tr></thead><tbody class="divide-y"><tr v-for="item in items" :key="item.id"><td class="p-4 font-mono">{{item.code}}</td><td class="p-4 font-semibold">{{item.name}}</td><td class="p-4">{{item.address||'—'}}</td><td class="p-4"><StatusBadge :value="item.status" /></td></tr><tr v-if="!items.length"><td colspan="4" class="p-8 text-center text-slate-400">Chưa có kho hàng.</td></tr></tbody></table></div></section></template>
